options=[
 dict(id='01-pebble',name='Pebble',tag='The balanced evolution',slim='Pinch the waist; keep fullness only at the shoulders.',housing='Two compact packs stay side by side underneath. A shaped upper cover follows the electronics and shoulder volumes; a recessed dark cassette carries the visual depth.',detail='A continuous highlight runs from nose to tail. Shallow shoulder scallops, flush caps and a soft edge replace the current straight side wall and repeated rings.',trade='Least disruption to the battery arrangement. Narrowing the waist still requires moving the chassis rails and checking inward leg sweep. The motor-to-motor width does not shrink with the waist.',weight='Reduce full-width side panels and redundant covers. A sculpted cover alone does not establish a weight saving.',risk='Lower packaging change',score='Best first CAD evolution',kind='paired'),
 dict(id='02-keel',name='Keel',tag='The narrow fuselage',slim='Move the packs into one long centerline keel.',housing='The two 125 × 85 × 65 mm pack envelopes sit one behind the other. The body becomes narrow between separate shoulder stations; short structural carriers remain visible.',detail='A canoe-like upper shell and a deep graphite keel produce a very lean top view. Clean metal crossmembers and exposed articulation give it a deliberate mechanical character.',trade='Tandem packs overlap the current roll-motor stations in plan view. They likely need to move roughly 30–40 mm lower, or require a larger actuator rearrangement. That is a poor trade for stair clearance.',weight='Longer battery rails, a skid and extended carriers can offset shell savings. Narrower does not necessarily mean lighter.',risk='Major packaging change',score='Narrowest center body',kind='tandem'),
 dict(id='03-twin-rail',name='Twin Rail',tag='The open-center instrument',slim='Replace the large trunk with two equipment rails and an open channel.',housing='One battery sits below each rail, with electronics above. Moving pack centers to about ±60 mm leaves a 35 mm gap between the assumed 85 mm-wide packs. Front and rear bridges connect the rails.',detail='Two sculpted ivory pods, slender metal bridges and a visible center channel make the torso feel lighter. Camera and lidar mounts become parts of the bridges rather than separate towers.',trade='The crossbridges must resist twisting, and cable paths need protection. A removable cargo bridge would partly fill the open channel. The front roll-axis supports need a new structural layout.',weight='Offers a route to deleting a central lid and tray, but bridge stiffness may consume the saving. The open area must be real structure removal, not a decorative recess.',risk='New chassis architecture',score='Most distinctive architecture',kind='split'),
 dict(id='04-manta',name='Manta',tag='The shallow sculpted canopy',slim='Use a thin visible edge, recessed flanks and local shoulder covers.',housing='Keep the batteries side by side. Spread low-profile electronics across the upper deck and reserve taller covers for components that need them. The dark belly remains deep enough to contain the packs.',detail='A subtle crown, swept shoulder scallops, generous undercuts and a flush camera visor create a fluid silhouette. Small black gaps preserve the independence of the moving shoulders.',trade='This primarily reduces perceived thickness. The 65 mm-tall packs still set a hard packaging floor, and heat sinks need room. Avoid unsupported thin overhangs or a rigid canopy crossing hip roll.',weight='Use the canopy as the actual removable enclosure and eliminate duplicate inner covers. Do not add it over the existing body shell.',risk='Moderate packaging change',score='Recommended exterior direction',kind='paired')
]

def plan(kind):
 # Schematic XY projection. Battery rectangles preserve the current envelope proportions;
 # shoulder symbols simplify complete stations and are not motor collision geometry.
 svg=['<svg viewBox="0 0 500 280" role="img" aria-label="Battery and equipment packaging plan"><rect width="500" height="280" rx="16" fill="#e6e7df"/>']
 if kind=='tandem':
  shape='<rect x="37" y="80" width="426" height="120" rx="55"/>'
  packs=[(120,97.5),(255,97.5)]
 elif kind=='split':
  shape='<rect x="38" y="32" width="424" height="96" rx="38"/><rect x="38" y="152" width="424" height="96" rx="38"/><path d="M75 115V165M425 115V165" stroke="#788278" stroke-width="14"/>'
  packs=[(187.5,37.5),(187.5,157.5)]
 else:
  shape='<path d="M45 65Q80 12 150 40Q250 48 350 40Q420 12 455 65L455 215Q420 268 350 240Q250 232 150 240Q80 268 45 215Z"/>'
  packs=[(187.5,53),(187.5,142)]
 svg.append('<g fill="#f8f6ed" stroke="#b4b9ac" stroke-width="1.4">'+shape+'</g>')
 for x in [65,435]:
  for y in [57,223]:svg.append(f'<circle cx="{x}" cy="{y}" r="27" fill="#323d36"/><circle cx="{x}" cy="{y}" r="17" fill="#8f988d"/>')
 for i,(x,y) in enumerate(packs):
  svg.append(f'<rect x="{x}" y="{y}" width="125" height="85" rx="9" fill="#f5b17f" stroke="#a35425"/><text x="{x+62.5}" y="{y+46}" text-anchor="middle" font-family="sans-serif" font-size="17" fill="#402c1c">Pack {i+1}</text>')
 svg.append('<text x="250" y="274" text-anchor="middle" font-family="sans-serif" font-size="11" fill="#526052">Battery arrangement only · simplified shoulder stations · front →</text></svg>')
 return ''.join(svg)

